// Validates neighbours, distances and directions generated by `npm run data` (also run alone by
// `npm run data:proximity`). If one fails, fix scripts/proximity.mjs and regenerate.
import { geoContains } from 'd3-geo';
import { feature } from 'topojson-client';
import type { GeometryCollection, Topology } from 'topojson-specification';
import countriesJson from '../../../../public/data/countries.json';
import neighborsJson from '../../../../public/data/neighbors.json';
import brazilProximityJson from '../../../../public/data/proximity-brazil.json';
import worldTerritoriesJson from '../../../../public/data/proximity-world-territories.json';
import worldProximityJson from '../../../../public/data/proximity-world.json';
import statesJson from '../../../../public/data/states.json';
import territoriesJson from '../../../../public/data/territories.json';
import crossingsJson from '../../../../public/data/trail-crossings.json';
import worldTopo from '../../../../public/data/world.topo.json';
import decisionsJson from '../../../../scripts/decisions.json';
import { BrazilState, Country, Territory, WorldUnitProperties } from './geo-data.models';
import {
  CrossingsData,
  NeighborsData,
  ProximityData,
  approxKm,
  directionSector,
  distanceKm,
  pairKey,
} from './proximity';

const neighbors = neighborsJson as NeighborsData;
const countries = countriesJson as unknown as Country[];
const territories = territoriesJson as unknown as Territory[];
const states = statesJson as unknown as BrazilState[];
const worldIds = countries.map((c) => c.id);
const allIds = [...worldIds, ...territories.map((t) => t.id)];
const stateIds = states.map((s) => s.id);

const files = {
  'territories off': {
    ids: worldIds,
    graph: neighbors.world.territoriesOff,
    data: worldProximityJson as ProximityData,
  },
  'territories on': {
    ids: allIds,
    graph: neighbors.world.territoriesOn,
    data: worldTerritoriesJson as ProximityData,
  },
  Brazil: {
    ids: stateIds,
    graph: neighbors.brazil,
    data: brazilProximityJson as ProximityData,
  },
};

describe('neighbours', () => {
  for (const [name, { graph, ids }] of Object.entries(files)) {
    it(`${name}: only known places, and a border is always mutual`, () => {
      for (const [id, list] of Object.entries(graph)) {
        expect(ids).toContain(id);
        expect(list).not.toContain(id);
        for (const other of list) {
          expect(ids).toContain(other);
          expect(graph[other]).toContain(id);
        }
      }
    });
  }

  it('Brazil has 10 neighbours with territories off, France among them', () => {
    const list = neighbors.world.territoriesOff['BRA'];
    expect(list.length).toBe(10);
    expect(list).toContain('FRA');
    expect(list).toEqual(expect.arrayContaining(['ARG', 'BOL', 'COL', 'GUY', 'PER', 'PRY']));
    expect(list).not.toContain('CHL');
    expect(list).not.toContain('ECU');
  });

  it('France reaches Brazil through French Guiana, and says so', () => {
    expect(neighbors.world.via[pairKey('FRA', 'BRA')]).toEqual(['GUF']);
    expect(neighbors.world.via[pairKey('FRA', 'SUR')]).toEqual(['GUF']);
    // With territories on the border belongs to the territory.
    expect(neighbors.world.territoriesOn['BRA']).toContain('GUF');
    expect(neighbors.world.territoriesOn['BRA']).not.toContain('FRA');
    expect(neighbors.world.territoriesOn['GUF']).toEqual(['BRA', 'SUR']);
  });

  it('every border listed in via is a border, made by a territory of one of the two', () => {
    for (const [key, via] of Object.entries(neighbors.world.via)) {
      const [a, b] = key.split('|');
      expect(neighbors.world.territoriesOff[a]).toContain(b);
      for (const id of via) {
        const territory = territories.find((t) => t.id === id);
        expect([a, b]).toContain(territory?.administeredBy);
      }
    }
  });

  it('borders between the own land of two countries stay when territories are on', () => {
    for (const [a, list] of Object.entries(neighbors.world.territoriesOff)) {
      for (const b of list) {
        if (neighbors.world.via[pairKey(a, b)]) continue;
        expect(neighbors.world.territoriesOn[a]).toContain(b);
      }
    }
  });

  it('islands have no land neighbours (Japan, Australia...)', () => {
    for (const id of ['JPN', 'AUS', 'NZL', 'ISL', 'MDG', 'CUB']) {
      expect(neighbors.world.territoriesOff[id] ?? []).toEqual([]);
      expect(neighbors.world.territoriesOn[id] ?? []).toEqual([]);
    }
  });

  it('a country inside another still borders it (Vatican, Lesotho)', () => {
    expect(neighbors.world.territoriesOff['VAT']).toEqual(['ITA']);
    expect(neighbors.world.territoriesOff['LSO']).toEqual(['ZAF']);
  });

  it('borders the simplified map loses are added by hand (Spain–Morocco, Macau–China)', () => {
    expect(neighbors.world.territoriesOff['ESP']).toContain('MAR');
    expect(neighbors.world.territoriesOn['MAR']).toContain('ESP');
    expect(neighbors.world.territoriesOn['MAC']).toEqual(['CHN']);
    expect(neighbors.world.territoriesOn['CHN']).toContain('MAC');
    // With territories off Macau is China itself: no border to speak of.
    expect(neighbors.world.territoriesOff['CHN']).not.toContain('CHN');
  });

  it('Trail: a border through a territory counts only on the same continent', () => {
    const trail = neighbors.world.trail;
    expect(trail['ESP']).toContain('GBR'); // Gibraltar
    expect(trail['BRA']).not.toContain('FRA'); // French Guiana
    expect(trail['BRA'].length).toBe(9);
    expect(trail['NLD'] ?? []).not.toContain('FRA'); // Saint-Martin
    expect(trail['GBR']).not.toContain('CYP'); // Akrotiri and Dhekelia
    expect(trail['CYP'] ?? []).toEqual([]);
    for (const [a, list] of Object.entries(trail)) {
      for (const b of list) {
        expect(neighbors.world.territoriesOff[a]).toContain(b);
        expect(trail[b]).toContain(a);
      }
    }
  });

  it('Trail with territories on: territories border on their own, the British bases do not count', () => {
    const trail = neighbors.world.trailTerritories;
    expect(neighbors.world.territoriesOn['CYP']).toContain('GBR'); // the map does not split the bases
    expect(trail['CYP'] ?? []).toEqual([]);
    expect(trail['GBR']).toEqual(['IRL']);
    expect(trail['GUF']).toEqual(expect.arrayContaining(['BRA', 'SUR']));
    expect(trail['GIB']).toEqual(['ESP']);
    for (const [a, list] of Object.entries(trail)) {
      for (const b of list) {
        expect(neighbors.world.territoriesOn[a]).toContain(b);
        expect(trail[b]).toContain(a);
      }
    }
  });

  it('places nobody administers only border others when territories are on', () => {
    expect(neighbors.world.territoriesOn['KOS']).toEqual(expect.arrayContaining(['SRB', 'ALB']));
    expect(neighbors.world.territoriesOff['SRB']).not.toContain('KOS');
  });

  it('Brazilian states: São Paulo has four neighbours, none is alone', () => {
    expect(neighbors.brazil['SP']).toEqual(['MG', 'MS', 'PR', 'RJ']);
    for (const id of stateIds) expect(neighbors.brazil[id].length).toBeGreaterThan(0);
  });
});

describe('sea crossings of the Trail', () => {
  const crossings = crossingsJson as unknown as CrossingsData;
  const { maxKm, maxIslandGroup } = decisionsJson.trailCrossings;

  /** The places joined by the edges of a graph, as sets of ids. */
  function groupsOf(ids: string[], graph: Record<string, string[]>): Set<string>[] {
    const groups: Set<string>[] = [];
    for (const id of ids) {
      if (groups.some((group) => group.has(id))) continue;
      const group = new Set([id]);
      // The set grows while it is walked: for-of keeps going until it is empty.
      for (const place of group) for (const next of graph[place] ?? []) group.add(next);
      groups.push(group);
    }
    return groups;
  }

  const rules = {
    off: {
      ids: worldIds,
      borders: neighbors.world.trail,
      proximity: worldProximityJson as ProximityData,
    },
    on: {
      ids: allIds,
      borders: neighbors.world.trailTerritories,
      proximity: worldTerritoriesJson as ProximityData,
    },
  };

  for (const rule of ['off', 'on'] as const) {
    const { ids, borders, proximity } = rules[rule];
    const list = crossings[rule];
    // A border that only exists through a territory does not make a place continental.
    const ownLand = Object.fromEntries(
      Object.entries(borders).map(([id, others]) => [
        id,
        rule === 'on' ? others : others.filter((other) => !neighbors.world.via[pairKey(id, other)]),
      ]),
    );
    const islandGroups = groupsOf(ids, ownLand).filter((group) => group.size <= maxIslandGroup);
    const islands = new Set(islandGroups.flatMap((group) => [...group]));

    it(`territories ${rule}: known places, each pair once, never a border`, () => {
      const pairs = list.map(({ a, b }) => `${a}|${b}`);
      expect(new Set(pairs).size).toBe(pairs.length);
      for (const { a, b } of list) {
        // One entry per pair, in order: the same crossing from either side.
        expect(a < b, `${a}-${b}`).toBe(true);
        expect(ids).toContain(a);
        expect(ids).toContain(b);
        expect(borders[a] ?? []).not.toContain(b);
      }
    });

    it(`territories ${rule}: at least one end is an island`, () => {
      for (const { a, b } of list) {
        expect(islands.has(a) || islands.has(b), `${a}-${b}`).toBe(true);
      }
    });

    it(`territories ${rule}: every island is linked, and reaches a continent`, () => {
      const linked: Record<string, string[]> = {};
      for (const id of ids) linked[id] = [...(borders[id] ?? [])];
      for (const { a, b } of list) {
        linked[a].push(b);
        linked[b].push(a);
      }
      for (const group of islandGroups) {
        const out = [...group].some((id) => linked[id].some((other) => !group.has(other)));
        expect(out, [...group].join()).toBe(true);
      }
      for (const group of groupsOf(ids, linked)) {
        expect(
          [...group].some((id) => !islands.has(id)),
          [...group].join(),
        ).toBe(true);
      }
    });

    it(`territories ${rule}: within the limit, except the guaranteed ones`, () => {
      for (const { a, b, km, guarantee } of list) {
        if (guarantee) expect(km, `${a}-${b}`).toBeGreaterThan(maxKm);
        else expect(km, `${a}-${b}`).toBeLessThanOrEqual(maxKm);
        // Coast to coast can only be farther than border to border.
        expect(km, `${a}-${b}`).toBeGreaterThanOrEqual(distanceKm(proximity, a, b) - 1);
      }
    });

    it(`territories ${rule}: the two points are as far apart as the crossing`, () => {
      const rad = Math.PI / 180;
      for (const { a, b, km, from, to } of list) {
        const cos =
          Math.sin(from[1] * rad) * Math.sin(to[1] * rad) +
          Math.cos(from[1] * rad) * Math.cos(to[1] * rad) * Math.cos((from[0] - to[0]) * rad);
        // The points are rounded to 0.01°, about 1 km each.
        expect(Math.abs(Math.acos(Math.min(1, cos)) * 6371 - km), `${a}-${b}`).toBeLessThan(3);
      }
    });
  }

  it('territories off: no crossing has an end on a territory', () => {
    const topo = worldTopo as unknown as Topology<Record<string, GeometryCollection>>;
    const shapes = feature(topo, topo.objects['units']);
    const territoryShapes = shapes.features.filter(
      (f) => (f.properties as WorldUnitProperties).territory,
    );
    expect(territoryShapes.length).toBeGreaterThan(0);
    for (const { a, b, from, to } of crossings.off) {
      for (const [id, point] of [
        [a, from],
        [b, to],
      ] as const) {
        const inside = territoryShapes.find((shape) => geoContains(shape, [...point]));
        const name = (inside?.properties as WorldUnitProperties | undefined)?.territory;
        expect(name, `${a}-${b}: ponta de ${id} em território`).toBeUndefined();
      }
    }
  });

  it('links what it should and leaves out what it should not', () => {
    const has = (a: string, b: string) => crossings.off.some((c) => c.a === a && c.b === b);
    expect(has('FRA', 'GBR')).toBe(true);
    expect(has('JPN', 'KOR')).toBe(true);
    expect(has('AUS', 'PNG')).toBe(true);
    // Two continental masses.
    expect(has('DJI', 'YEM')).toBe(false);
    expect(has('RUS', 'USA')).toBe(false);
    expect(has('EGY', 'SAU')).toBe(false);
    // Only through a territory (Puerto Rico, Gibraltar, Jersey, Tokelau...): the territory counts
    // only when the option is on.
    expect(has('DOM', 'USA')).toBe(false);
    expect(has('GBR', 'MAR')).toBe(false);
    expect(has('KIR', 'NZL')).toBe(false);
    expect(crossings.off.filter((c) => [c.a, c.b].includes('FRA')).length).toBe(1);
    const hasOn = (a: string, b: string) => crossings.on.some((c) => c.a === a && c.b === b);
    expect(hasOn('DOM', 'PRI')).toBe(true);
    // Islands that belong to the country itself still count.
    expect(has('ITA', 'MLT')).toBe(true);
    // Only through the bases in Cyprus.
    expect(has('CYP', 'GBR')).toBe(false);
    expect(has('GBR', 'TUR')).toBe(false);
  });
});

describe('distances and directions', () => {
  for (const [name, { ids, graph, data }] of Object.entries(files)) {
    it(`${name}: same places as the game, one distance per pair`, () => {
      const n = ids.length;
      expect(data.ids).toEqual(ids);
      expect(data.km.length).toBe((n * (n - 1)) / 2);
      expect(data.dir.length).toBe(n);
      for (const row of data.dir) expect(row).toMatch(new RegExp(`^[0-9a-f.]{${n}}$`));
    });

    it(`${name}: neighbours are 0 km apart, everyone else at least 1 km`, () => {
      for (const a of data.ids) {
        for (const b of data.ids) {
          if (a >= b) continue;
          const km = distanceKm(data, a, b);
          if (graph[a]?.includes(b)) expect(km).toBe(0);
          else expect(km).toBeGreaterThanOrEqual(1);
        }
      }
    });

    it(`${name}: the distance is the same from either side`, () => {
      const [a, b, c] = [data.ids[0], data.ids[5], data.ids[9]];
      expect(distanceKm(data, a, b)).toBe(distanceKm(data, b, a));
      expect(distanceKm(data, a, c)).toBe(distanceKm(data, c, a));
    });
  }

  it('known distances are about right', () => {
    const world = worldProximityJson as ProximityData;
    expect(distanceKm(world, 'BRA', 'ARG')).toBe(0);
    expect(distanceKm(world, 'DNK', 'SWE')).toBeLessThan(20);
    expect(distanceKm(world, 'JPN', 'KOR')).toBeGreaterThan(30);
    expect(distanceKm(world, 'JPN', 'KOR')).toBeLessThan(100);
    expect(distanceKm(world, 'BRA', 'JPN')).toBeGreaterThan(12_000);
    expect(distanceKm(world, 'BRA', 'JPN')).toBeLessThan(16_000);
  });

  it('territories off: only the own land of a country counts, not its territories', () => {
    const world = worldProximityJson as ProximityData;
    // The Virgin Islands (British and American) are 7 km apart, but they are territories.
    expect(distanceKm(world, 'GBR', 'USA')).toBeGreaterThan(1000);
    // Metropolitan France is far from the Pacific, whatever it administers there.
    expect(distanceKm(world, 'FRA', 'NZL')).toBeGreaterThan(1000);
    // Territories on: each territory is a place of its own, so the Virgin Islands are close.
    const territoriesOn = worldTerritoriesJson as ProximityData;
    expect(distanceKm(territoriesOn, 'VGB', 'VIR')).toBeLessThan(20);
    // A border through a territory stays a border (Gibraltar, French Guiana).
    expect(distanceKm(world, 'ESP', 'GBR')).toBe(0);
    expect(distanceKm(world, 'BRA', 'FRA')).toBe(0);
    // An island of the country itself still counts (Sicily is Italian, so Malta is close).
    expect(distanceKm(world, 'ITA', 'MLT')).toBeLessThan(150);
  });

  it('on screen, distances are rounded to tens of km, and neighbours stay at 0', () => {
    expect(approxKm(0)).toBe(0);
    expect(approxKm(1)).toBe(10);
    expect(approxKm(14)).toBe(10);
    expect(approxKm(15)).toBe(20);
    expect(approxKm(1234)).toBe(1230);
  });

  it('directions point the right way (0 = north, 4 = east, 8 = south, 12 = west)', () => {
    const brazil = brazilProximityJson as ProximityData;
    expect(directionSector(brazil, 'SP', 'AM')).toBe(14); // north-west
    expect(directionSector(brazil, 'AM', 'SP')).toBe(6); // south-east
    const world = worldProximityJson as ProximityData;
    expect(directionSector(world, 'BRA', 'JPN')).toBeGreaterThanOrEqual(13);
    expect(directionSector(world, 'FRA', 'DEU')).toBeLessThanOrEqual(6);
  });
});
